-- Public lead intake RPC. Direct anonymous table inserts remain blocked by RLS.
create or replace function public.submit_public_lead(p_name text,p_phone text,p_need text default null,p_source_page text default null,p_utm_source text default null,p_utm_medium text default null,p_utm_campaign text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_phone text;v_contact uuid;v_lead uuid;begin if char_length(trim(coalesce(p_name,'')))<2 then raise exception 'invalid_name';end if;v_phone:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');if v_phone like '84%' then v_phone:='0'||substring(v_phone from 3);end if;if v_phone !~ '^0[0-9]{9,10}$' then raise exception 'invalid_phone';end if;select id into v_contact from contacts where phone_normalized=v_phone order by created_at desc limit 1;if v_contact is null then insert into contacts(name,phone,phone_normalized) values(trim(p_name),trim(p_phone),v_phone) returning id into v_contact;else update contacts set name=trim(p_name),phone=trim(p_phone),updated_at=now() where id=v_contact;end if;insert into leads(contact_id,need,status,source_type,source_page,utm_source,utm_medium,utm_campaign) values(v_contact,nullif(trim(p_need),''),'new','website',nullif(trim(p_source_page),''),nullif(trim(p_utm_source),''),nullif(trim(p_utm_medium),''),nullif(trim(p_utm_campaign),'')) returning id into v_lead;insert into lead_activities(lead_id,activity_type,to_status,note) values(v_lead,'created','new','Website lead intake');return v_lead;end $$;revoke all on function public.submit_public_lead(text,text,text,text,text,text,text) from public;grant execute on function public.submit_public_lead(text,text,text,text,text,text,text) to anon;